(async function(){
  var lb=Array.from(document.querySelectorAll("label")).find(function(e){return (e.textContent||"").trim()==="推广专区"});
  if(!lb) return "NO_LABEL";
  var dd=lb.parentElement.querySelector("[class*=dropdown]");
  if(!dd) return "NO_DD";
  if(dd.className.indexOf("active")<0) dd.click();
  await new Promise(function(r){setTimeout(r,800)});
  var menu=dd.querySelector("[class*=menu]");
  if(!menu) return "NO_MENU";
  var items=Array.from(menu.querySelectorAll("*")).filter(function(e){return (e.textContent||"").trim()==="AI & 大数据"&&e.children.length===0});
  if(!items.length) return "NOT_IN_MENU:"+(menu.textContent||"").slice(0,150);
  items[0].click();
  await new Promise(function(r){setTimeout(r,500)});
  var field=document.querySelector("select[name=groups],input[name=groups]");
  return "CLICKED, field="+(field?field.value:"?");
})()
